-- Prayers
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-anxious-thoughts', 'es', 'title', 'Cuando Los Pensamientos Ansiosos No Se Detienen');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-anxious-thoughts', 'es', 'description', 'Una oración para cuando tu mente se descontrola y no puedes encontrar el interruptor de apagado.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-anxious-thoughts', 'es', 'transcript', '# Cuando Los Pensamientos Ansiosos No Se Detienen

Señor, mi corazón se siente como una tormenta, y mi mente es un torbellino de preocupaciones. Vengo a Ti porque no sé cómo calmar este caos por mí mismo. Tú conoces cada pensamiento antes de que siquiera se forme en mi mente, y me siento tan abrumado por su constante agitación. Tu palabra dice: "Echando toda vuestra ansiedad sobre él, porque él tiene cuidado de vosotros." Anhelo hacer esto, pero el peso es tan grande, y mi agarre tan fuerte. Ayúdame, Dios, a liberar mis miedos en Tus manos capaces.

Necesito Tu paz, la paz que sobrepasa todo entendimiento. El tipo de paz que guarda mi corazón y mi mente, como una fortaleza en medio de esta tormenta. Confieso que a menudo confío en mi propia fuerza, y eso solo me deja más cansado. Enséñame a confiar más profundamente en Ti, a apoyarme en Tus promesas cuando me siento incierto y temeroso.

Padre, recuérdame que no estoy solo. Tú estás conmigo, incluso en los momentos más oscuros de mi ansiedad. Tu presencia es mi refugio. Ayúdame a descansar en Tu amor, sabiendo que Tú eres mi roca y mi salvación. Silencia mis pensamientos ansiosos, Señor, y lléname de Tu perfecta paz. Amén.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-overwhelmed', 'es', 'title', 'Cuando Estás Completamente Abrumado');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-overwhelmed', 'es', 'description', 'Todo es demasiado. Esta oración te ayuda a respirar y entregarlo.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-overwhelmed', 'es', 'transcript', '# Cuando Estás Completamente Abrumado

Dios, vengo a Ti con un corazón pesado y cargado. Todo parece que se está cerrando, y no puedo encontrar un terreno firme. Conoces el caos que me rodea y las preocupaciones que consumen mis pensamientos. Siento que me estoy ahogando, Señor, y necesito Tu mano firme para sacarme a la superficie. Prometes que estás cerca de los quebrantados de corazón y salvas a los abatidos de espíritu, y hoy me aferro a esa promesa.

Ayúdame, Padre, a entregar estos miedos en Tus manos capaces. Me siento atrapado en este ciclo de ansiedad, y necesito Tu paz, la paz que sobrepasa todo entendimiento, para guardar mi corazón y mi mente. Enséñame a confiar en Ti con todo mi corazón y no apoyarme en mi propio entendimiento, porque mi entendimiento está nublado y es limitado.

Tú ves el camino por delante, incluso cuando yo no puedo. Eres mi refugio y mi fortaleza, un auxilio siempre presente en las tribulaciones. Recuérdame que no estoy solo, que caminas conmigo a través de esta tormenta. Lléname de Tu valor y rodéame con Tu amor. Al enfrentar cada momento, ayúdame a respirar y a recordar que Tu gracia es suficiente para mí.

Amén.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-fear-of-future', 'es', 'title', 'Miedo al Futuro');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-fear-of-future', 'es', 'description', 'Cuando el mañana te aterroriza. Una oración para confiar en Aquel que lo sostiene.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-fear-of-future', 'es', 'transcript', '# Miedo al Futuro

Señor, vengo ante Ti con un corazón tembloroso, abrumado por las incertidumbres que el mañana trae. Tú conoces cada pensamiento que corre por mi mente, cada miedo que aprisiona mi espíritu. Lucho por ver el camino adelante, y las sombras de lo que podría ser se ciernen grandes en mi alma. Ayúdame, Señor, a recordar que Tú ya estás allí, en el futuro que temo. Prometes en Jeremías 29:11 que conoces los planes que tienes para mí, planes de bienestar y no de mal, para darme un futuro y una esperanza. Anhelo anclarme en esa promesa.

En mi debilidad, deposito mis miedos a Tus pies, pidiendo la paz que solo Tú puedes proporcionar. Enséñame a confiar en Tu bondad, a creer que Tu amor es firme e inmutable. Cuando el peso de mis preocupaciones se siente insoportable, recuérdame que no estoy solo, que Tú eres mi refugio y fortaleza.

Padre, ayúdame a soltar mi control sobre lo que no puedo manejar, y a poner mi futuro en Tus manos. Al enfrentar lo desconocido, lléname con la seguridad de que Tú eres el mismo ayer, hoy y siempre. Guíame con Tu luz, y concédeme el valor para caminar con valentía, sabiendo que Tú estás conmigo en cada paso del camino. Amén.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-peace-in-chaos', 'es', 'title', 'Paz en el Caos');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-peace-in-chaos', 'es', 'description', 'La tormenta está rugiendo pero Jesús está en el barco. Una oración por una calma sobrenatural.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-peace-in-chaos', 'es', 'transcript', '# Paz en el Caos

Oh Señor, mi corazón está pesado con el peso de la preocupación y el miedo. Las olas de ansiedad se estrellan sobre mí, y me encuentro luchando por mantenerme a flote. Vengo a Ti porque sé que Tú eres quien calma la tormenta. Así como Jesús se puso de pie en el barco y habló paz sobre las aguas, te pido que hables paz en mi corazón. Tú dijiste: "Echando toda vuestra ansiedad sobre él, porque él tiene cuidado de vosotros." Así que aquí estoy, Señor, echando cada miedo, cada pensamiento ansioso en Tus manos.

Me siento abrumado, Señor, como si estuviera atrapado en un torbellino de duda e incertidumbre. Pero sé que Tú eres mi refugio y fortaleza, un pronto auxilio en las tribulaciones. Recuérdame de Tu presencia cuando me sienta solo y asustado. Ayúdame a confiar en que Tú estás en control, incluso cuando todo a mi alrededor parece caótico.

Cuando mi mente corre y mi corazón late con fuerza, que Tu Espíritu susurre palabras de consuelo y verdad. Enséñame a inhalar Tu paz y exhalar mis preocupaciones, descansando en la seguridad de que Tú estás conmigo. Rodéame con Tu amor que echa fuera todo temor, y ancla mi alma en Tus promesas inmutables. Amén.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-letting-go-of-control', 'es', 'title', 'Dejando Ir el Control');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-letting-go-of-control', 'es', 'description', 'No puedes mantener todo bajo control. Una oración para soltar tu agarre y confiar en el plan de Dios.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-letting-go-of-control', 'es', 'transcript', '# Dejando Ir el Control

Querido Dios, vengo ante Ti sintiéndome abrumado y agobiado por todas las cosas que no puedo controlar. Mi corazón late con preocupación y mi mente está enredada en una red de ''qué pasaría si''. Confieso que intento mantener las cosas unidas por mi cuenta, pensando que si solo trabajo más duro, todo estará bien. Pero en el fondo, sé que no estoy en control, y eso me aterra.

Tú prometes que cuidas de mí, instándome a echar toda mi ansiedad sobre Ti. Es difícil soltar mi agarre, Señor, dejar ir las cosas a las que me aferro tan fuertemente. Ayúdame a confiar en Tu plan, incluso cuando el camino parece incierto y las sombras nublan mi visión. Recuérdame que Tus caminos son más altos que mis caminos, y Tus pensamientos son más altos que mis pensamientos.

Padre, concédeme la paz que sobrepasa todo entendimiento, guardando mi corazón y mi mente en Cristo Jesús. Ayúdame a rendir cada preocupación a Ti, una por una, creyendo que tienes mi futuro en Tus manos capaces. Cuando el miedo susurra mentiras, que Tu verdad hable más fuerte, llenándome con la seguridad de que Tú eres mi refugio y fortaleza, un auxilio siempre presente en la angustia.

En este momento de vulnerabilidad, elijo apoyarme en Ti, sabiendo que Tu gracia es suficiente para mí. Gracias por ser mi roca constante e inmutable en un mundo que se siente tan incierto. Amén.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-cant-sleep', 'es', 'title', 'Cuando No Puedes Dormir');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-cant-sleep', 'es', 'description', 'Tu cuerpo está cansado pero tu mente no se detiene. Deja que esta oración te lleve al descanso.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-cant-sleep', 'es', 'transcript', '# Cuando No Puedes Dormir

Dios, aquí estoy, despierto mientras mi mente corre con pensamientos que no se aquietan. Estoy cansado, y sin embargo el descanso parece tan lejano. Conoces mis pensamientos desde lejos, incluso los ansiosos que me mantienen dando vueltas. Padre, me siento tan pequeño bajo el peso de estas preocupaciones interminables. Tu Palabra nos dice que echemos nuestras cargas sobre Ti porque Tú cuidas de nosotros, y esta noche, traigo todas estas preocupaciones a Tus pies.

Por favor, calma mi mente, Señor. El salmista dice: "En paz me acostaré, y asimismo dormiré; porque solo tú, Señor, me haces vivir confiado." Anhelo esa paz, ese susurro suave de Tu presencia que calma cada tormenta dentro de mí. Ayúdame a rendir estos pensamientos inquietos a Ti, creyendo que tienes el mañana seguro en Tus manos.

Abrázame con Tu amor y ayúdame a respirar profundamente de Tu gracia. Que Tu paz, que sobrepasa todo entendimiento, guarde mi corazón y mi mente en Cristo Jesús. Confío en que velarás por mí mientras duermo, renovarás mi fuerza, y me despertarás con la fresca esperanza de un nuevo día. Amén.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-nighttime-peace', 'es', 'title', 'Paz Nocturna');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-nighttime-peace', 'es', 'description', 'Una oración suave para cerrar el día, soltar el peso y dormir en los brazos de Dios.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-nighttime-peace', 'es', 'transcript', '# Paz Nocturna

Querido Dios, al llegar el final del día, vengo a Ti con un corazón lleno de gratitud y cargas que anhelo dejar a un lado. Tú conoces cada detalle de mi día, los momentos de alegría y las luchas que persisten en mi mente. Pido que Tu paz me envuelva, calmando mis pensamientos inquietos y trayendo quietud a mi alma. Tu palabra me recuerda, "A su amado dará Dios el sueño." Que pueda confiar en esa promesa esta noche.

Ayúdame a liberar el peso de la preocupación y la ansiedad, permitiendo que Tu presencia gentil me arrulle en un descanso profundo. Anhelo que mi mente se aquiete, libre del ruido del mundo, para que pueda escuchar Tus susurros de amor y seguridad. Guía mis sueños, Señor, y llénalos con Tu luz y esperanza.

Que mi sueño sea un tiempo de renovación, un espacio sagrado donde Tú restaures mi fuerza y me prepares para el día que viene. Entrego mis miedos e incertidumbres a Ti, confiado en Tu protección durante la noche. En Tus brazos encuentro seguridad y consuelo, sabiendo que me cuidas con ternura. Amén.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-rest-for-weary', 'es', 'title', 'Descanso para el Cansado');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-rest-for-weary', 'es', 'description', 'Venid a mí, todos los que estáis trabajados. Una oración para los agotados y quemados.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-rest-for-weary', 'es', 'transcript', '# Descanso para el Cansado

Querido Señor, vengo a Ti en mi agotamiento, buscando el descanso que solo Tú puedes proporcionar. Mi cuerpo se siente pesado y mi mente está llena de preocupaciones que roban mi paz. Estoy cansado, Señor, y necesito Tu consuelo. Tú prometes en Tu palabra, "Venid a mí todos los que estáis trabajados y cargados, y yo os haré descansar." Me aferro a esta promesa ahora, confiando en que aliviarás mis cargas y renovarás mis fuerzas. Silencia mis pensamientos acelerados y calma la tormenta dentro de mí. Dejo mis ansiedades a Tus pies, sabiendo que Te preocupas por mí más de lo que puedo comprender.

Ayúdame a soltar el control y confiar en Tu plan, porque Tú sabes lo que es mejor para mí. Al cerrar mis ojos, deja que Tu paz me inunde, una paz que sobrepasa todo entendimiento. Recuérdame que no estoy solo, que Tú estás conmigo en cada paso del camino, incluso en mis sueños. Restaura mi alma, Señor, y que mi sueño sea dulce. Entrego mi fatiga a Ti, sabiendo que Tú eres mi refugio y fortaleza. Gracias por ser mi lugar de descanso. Amén.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-trusting-through-night', 'es', 'title', 'Confiando en Dios Durante la Noche');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-trusting-through-night', 'es', 'description', 'La oscuridad se siente pesada. Pero la mañana viene. Una oración por fe en las horas oscuras.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-trusting-through-night', 'es', 'transcript', '# Confiando en Dios Durante la Noche

Querido Señor, al acostarme esta noche, me encuentro rodeado de oscuridad, tanto afuera como dentro de mí. El sueño parece esquivo, y mi mente corre con preocupaciones y miedos que parecen hacerse más fuertes en el silencio de la noche. Conoces mi corazón, Señor, y cuánto anhelo desesperadamente descansar. Me recuerdas en Tu palabra que das sueño a aquellos que amas. Ayúdame a aferrarme a esa promesa ahora.

Padre, lucho por soltar las cargas del día. Cada pensamiento y preocupación los pongo ante Ti, sabiendo que eres mayor que cualquier cosa que enfrente. Tú, que creaste las estrellas y las llamas a cada una por su nombre, seguramente puedes manejar lo que me preocupa. Confío en que Tu ojo vigilante está sobre mí incluso ahora, que nunca duermes ni te adormeces.

Por favor, envuélveme en Tu paz, una paz que sobrepasa todo entendimiento. Guarda mi corazón y mi mente mientras descanso en Ti. Como dijo el salmista: "Yo me acuesto y duermo, y vuelvo a despertar, porque el Señor me sostiene." Sostenme durante esta noche, Señor, y permíteme despertar renovado, listo para encontrar las nuevas misericordias que has preparado para mí. Gracias por ser mi refugio y fortaleza, una ayuda siempre presente en tiempos de angustia. Pongo mi confianza en Ti esta noche, creyendo que la mañana traerá nueva esperanza. Amén.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-surrender-before-sleep', 'es', 'title', 'Entrega Antes de Dormir');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-surrender-before-sleep', 'es', 'description', 'Entrega el día: los logros, los fracasos, lo desconocido. Duerme libre.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-surrender-before-sleep', 'es', 'transcript', '# Entrega Antes de Dormir

Querido Dios, al acostarme esta noche, te traigo el día que ha pasado. Tú conoces cada momento, cada alegría y cada lucha. Te ofrezco todo lo que he logrado y todo donde he fallado. Tu Palabra dice que a Tus amados darás el sueño, y anhelo el descanso que solo Tú puedes proporcionar. Señor, estoy cansado y necesito Tu paz.

Ayúdame a soltar las cargas que llevo, las preocupaciones que permanecen en mi mente y los temores sobre el mañana. Me recuerdas que Tus misericordias son nuevas cada mañana, así que confío en que en la luz de la mañana, Tu gracia me encontrará de nuevo. Cubre mi sueño con Tu protección y que mis sueños estén llenos de Tu paz.

Te entrego las cosas que no puedo cambiar y las incertidumbres que esperan. Que Tu Espíritu me cubra, calmando mi corazón ansioso. Al cerrar mis ojos, déjame sentir la seguridad de Tu presencia, sabiendo que siempre estás conmigo. Gracias por ser mi refugio y fortaleza. Descanso en Tu amor esta noche, Padre. Amén.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-thankful-heart', 'es', 'title', 'Un Corazón Agradecido');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-thankful-heart', 'es', 'description', 'Una oración para notar lo bueno, incluso en temporadas difíciles. La gratitud lo cambia todo.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-thankful-heart', 'es', 'transcript', '# Un Corazón Agradecido

Dios, vengo a Ti con un corazón lleno de gratitud, incluso cuando la vida se siente pesada. En estos momentos, quiero levantar mis ojos hacia Ti y ver las bendiciones que derramas sobre mí. Te agradezco por el aliento en mis pulmones, por el amanecer que pinta el cielo, y por los pequeños actos de bondad que susurran Tu amor hacia mí. Me recuerdas que "toda buena dádiva y todo don perfecto desciende de lo alto", y por eso, estoy agradecido.

Ayúdame a ver Tu mano en lo cotidiano y lo ordinario. Incluso en temporadas de dificultad, elijo confiar en Tu bondad y fidelidad. Te agradezco por las lecciones que vienen envueltas en desafíos, porque me enseñan resiliencia y me acercan más a Ti. Tú eres mi refugio y mi fortaleza, y te alabo por ser mi fuente constante de esperanza.

Dios, cultiva en mí un corazón que desborde de agradecimiento. Que la gratitud sea mi estado natural, no solo cuando la vida es fácil, sino también cuando el camino es difícil. Quiero vivir con un espíritu de alabanza que te honre y reconozca la belleza que tejes en cada día. Gracias por Tu gracia y amor interminables. Amén.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-praise-in-storm', 'es', 'title', 'Alabanza en la Tormenta');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-praise-in-storm', 'es', 'description', 'Todo se está desmoronando, pero eliges adorar de todas formas. Una oración de alabanza desafiante.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-praise-in-storm', 'es', 'transcript', '# Alabanza en la Tormenta

Oh Señor, incluso cuando los vientos rugen y las nubes de tormenta se juntan, levanto mi voz para alabarte. Tú eres mi refugio y mi fortaleza, mi Dios, en quien confío. Aunque el mundo a mi alrededor tiemble, Tú permaneces inmutable y Tu amor infalible. Elijo ver Tu mano obrando, incluso en el caos, creyendo que Tú haces que todas las cosas obren para bien. Cuando mi corazón está abrumado, llévame a la roca que es más alta que yo. Tu presencia es mi refugio, Tus promesas mi esperanza.

Padre, me acuerdo de Pablo y Silas en aquella oscura prisión, cantándote himnos a pesar de sus cadenas. Quiero levantar mi corazón en la misma alabanza desafiante, sabiendo que Tú habitas en las alabanzas de Tu pueblo. Te agradezco por Tu amor inquebrantable, por Tus misericordias que son nuevas cada mañana, incluso cuando la noche parece interminable. Tú eres mi luz y mi salvación; ¿de quién temeré? En Tu fuerza, encuentro el valor para enfrentar cada día.

Gracias por ser la calma en mi tormenta, por Tu paz que sobrepasa todo entendimiento. Te alabo, no por mis circunstancias, sino por quien Tú eres. Amén.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-morning-gratitude', 'es', 'title', 'Gratitud Matutina');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-morning-gratitude', 'es', 'description', 'Comienza el día con los ojos bien abiertos a la bondad de Dios. Una oración para mañanas frescas.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-morning-gratitude', 'es', 'transcript', '# Gratitud Matutina

Padre Celestial, mientras la luz de la mañana rompe la oscuridad, levanto mi corazón a Ti en gratitud. Gracias por el regalo de un nuevo día, un nuevo comienzo lleno de posibilidades. Tus misericordias son nuevas cada mañana, y estoy tan agradecido por el aliento en mis pulmones y el latido de mi corazón. Tu fidelidad, Señor, llega hasta los cielos, y me recuerda que Tu amor nunca falla.

Gracias por la belleza de la creación que me rodea, por el sol que se levanta fielmente cada día, recordándome Tu presencia constante. Te alabo por las pequeñas maravillas y los grandes milagros que llenan mi vida. Ayúdame a verlos claramente hoy, a caminar con los ojos bien abiertos a Tu bondad y gracia.

Señor, como dijo el salmista, "Este es el día que hizo Jehová; nos gozaremos y alegraremos en él." Elijo entrar en este día con alegría y anticipación, sabiendo que Tú tienes cada momento en Tus manos. Que mi corazón rebose de gratitud por las bendiciones vistas e invisibles, confiando en que Tú estás obrando todas las cosas para mi bien.

Guía mis pasos, Señor, y llena mi corazón con Tu paz y alegría. Que mi vida refleje Tu luz mientras me muevo a través del día con agradecimiento. Amén.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-counting-blessings', 'es', 'title', 'Contando Bendiciones');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-counting-blessings', 'es', 'description', 'Cuando olvidas cuán bueno ha sido Dios. Una oración para recordar y dar gracias.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-counting-blessings', 'es', 'transcript', '# Contando Bendiciones

Oh Señor, mi corazón rebosa de gratitud al presentarme ante Ti. En el ajetreo de la vida, confieso que a menudo olvido las innumerables maneras en que me has bendecido. Hoy, me detengo para reflexionar sobre Tu bondad y dar gracias. Tus misericordias son nuevas cada mañana, y Tu fidelidad es grande más allá de toda medida. Recuerdo las veces en que me levantaste de las profundidades de la desesperación y pusiste mis pies en tierra firme. ¡Cuán preciosos son Tus pensamientos hacia mí, oh Dios, cuán grande es la suma de ellos!

Gracias por el don de la vida y el aliento que llena mis pulmones. Gracias por la belleza de la creación que me rodea, un recordatorio constante de Tu gloria. Has provisto para mis necesidades y has llenado mi copa hasta rebosar. Como declara el salmista: “Bendice, alma mía, a Jehová, y no olvides ninguno de sus beneficios.” Tú sanas mis enfermedades, redimes mi vida del hoyo, y me coronas de amor y misericordia.

En momentos de duda, ayúdame a recordar Tu fidelidad pasada. Que la gratitud sea mi canción y la acción de gracias mi himno. Con un corazón lleno de agradecimiento, te alabo, porque Tú eres bueno y Tu amor perdura para siempre. Amén.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-joy-in-small-things', 'es', 'title', 'Alegría en las Cosas Pequeñas');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-joy-in-small-things', 'es', 'description', 'Los grandes milagros son raros. Las pequeñas misericordias son diarias. Una oración para verlas.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-joy-in-small-things', 'es', 'transcript', '# Alegría en las Cosas Pequeñas

Padre, vengo a Ti con un corazón lleno de gratitud por las innumerables pequeñas misericordias que llenan mis días. A veces me pierdo tanto esperando los grandes milagros que paso por alto los suaves susurros de Tu bondad en los momentos cotidianos. Abre mis ojos para ver la belleza en las cosas simples—una taza de café caliente, una palabra amable de un amigo, la risa de un niño. Estas son las bendiciones que me recuerdan Tu amor constante.

Señor, Tu Palabra nos dice que toda buena dádiva y todo don perfecto desciende de lo alto, del Padre de las luces. Cuántas veces olvido que estos regalos me rodean diariamente, esperando silenciosamente mi reconocimiento. Ayúdame a reconocer y atesorar estos momentos, sabiendo que son evidencia de Tu cuidado inquebrantable.

Enséñame a encontrar alegría en las cosas pequeñas, a apreciar el sol de la mañana en mi rostro y la brisa fresca que lleva Tu paz. Que mi corazón esté afinado para cantar Tus alabanzas por estas misericordias diarias, pues son reflejos de Tu fidelidad. Que mi gratitud por estas pequeñas alegrías me acerque más a Ti, profundizando mi confianza y amor por Ti cada día. Gracias por llenar mi vida con Tu gracia sutil pero profunda. Amén.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-physical-healing', 'es', 'title', 'Oración por Sanidad Física');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-physical-healing', 'es', 'description', 'Tu cuerpo está roto. Llévalo al Sanador. Una oración por restauración.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-physical-healing', 'es', 'transcript', '# Oración por Sanidad Física

Padre, vengo ante Ti sintiéndome débil y quebrantado. Mi cuerpo lucha bajo el peso de la enfermedad, y anhelo Tu toque sanador. Me has creado con tanto cuidado, entretejido de manera intrincada. Sé que ves cada parte de mí y entiendes mi dolor. Tu palabra me recuerda que Tú eres el Señor que sana, y me aferro a esa promesa con todo mi corazón.

Cuando estoy cansado y agobiado, me invitas a venir a Ti para descansar. Deposito mis preocupaciones y temores a Tus pies, confiando en que estás cerca de aquellos que te invocan de verdad. Por favor, Señor, trae restauración a mi cuerpo. Que Tu poder sanador fluya a través de cada parte de mí, renovando y reviviendo lo que está roto.

Tú eres mi fortaleza, mi refugio en tiempos de angustia. Incluso mientras camino por este valle, no temeré, porque Tú estás conmigo. Señor, concédeme paciencia y valor mientras espero Tu sanidad. Ayúdame a encontrar consuelo en Tu presencia y a confiar en Tu perfecto tiempo. Gracias por ser mi Sanador y mi esperanza. Pongo mi cuerpo y mi vida en Tus manos, sabiendo que eres capaz de hacer mucho más de lo que puedo pedir o imaginar. Amén.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-emotional-healing', 'es', 'title', 'Oración por la Sanación Emocional');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-emotional-healing', 'es', 'description', 'La herida no es visible pero es real. Una oración por las cicatrices internas.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-emotional-healing', 'es', 'transcript', '# Oración por la Sanación Emocional

Señor, vengo ante Ti con un corazón que se siente pesado y herido. Tú ves las cicatrices que yacen en lo profundo, esos lugares ocultos que nadie más puede tocar. Me recuerda Tu promesa en el Salmo 34:18 que estás cerca de los quebrantados de corazón y salvas a los de espíritu abatido. Dios, necesito Tu cercanía ahora más que nunca. Por favor, toca estas heridas invisibles con Tus manos sanadoras. Ayúdame a liberar el dolor y permite que Tu paz llene los espacios donde el dolor se ha asentado.

Conoces cada lágrima que he llorado y cada noche sin dormir. Te pido la fuerza para perdonar donde necesito perdonar, para soltar la amargura y la ira que enredan mi alma. Tú eres el Gran Sanador, y confío en Tu poder para restaurar mi espíritu. Envuélveme en Tu amor, Señor, y recuérdame que no estoy solo en este camino. Guíame a Tu verdad y ayúdame a encontrar alegría en medio del dolor.

Gracias por ser mi refugio y mi consuelo. Coloco mi corazón en Tus manos, confiando en que lo sanarás en Tu perfecto tiempo. Amén.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-healing-for-loved-one', 'es', 'title', 'Sanación para un Ser Querido');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-healing-for-loved-one', 'es', 'description', 'Alguien a quien amas está sufriendo y te sientes impotente. Ora de todos modos.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-healing-for-loved-one', 'es', 'transcript', '# Sanación para un Ser Querido

Oh Señor, vengo a Ti con un corazón cargado de preocupación por alguien a quien tengo en gran estima. Tú conoces su sufrimiento, su dolor y sus luchas mejor de lo que yo jamás podría. En momentos como estos, me siento tan impotente, pero sé que Tú no lo eres. Tú eres el gran Sanador, el que nos tejió en el vientre de nuestra madre, y confío en Tu poder para restaurar y renovar.

Padre, pido Tu toque sanador sobre ellos. Llega a lo más profundo de su ser y trae consuelo donde hay dolor, fortaleza donde hay debilidad. Tu palabra nos dice que sanas a los quebrantados de corazón y vendan sus heridas. Me aferro a esta promesa, confiando en que traerás paz a su cuerpo y mente atribulados.

Admito, Señor, que el miedo intenta colarse, y la duda susurra en mi oído. Pero elijo aferrarme a la fe, creyendo que Tu amor echa fuera todo temor. Guía las manos de quienes los cuidan y concede sabiduría a quienes toman decisiones sobre su tratamiento.

Señor, envuélvelos en Tu amor y haz que sientan Tu presencia. Incluso cuando no puedo estar allí, sé que Tú estás. Danos a ambos la paciencia y la fortaleza para soportar esta temporada. Dejo mis preocupaciones a Tus pies, confiando en Tu perfecta voluntad. Amén.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-chronic-pain', 'es', 'title', 'Cuando la Sanación No Llega');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-chronic-pain', 'es', 'description', 'Has orado. Nada cambió. Una oración por resistencia cuando Dios parece estar en silencio.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-chronic-pain', 'es', 'transcript', '# Cuando la Sanación No Llega

Oh Señor, vengo a Ti cansado y cargado, luchando bajo el peso de las oraciones no respondidas. He pedido sanación, pero mi cuerpo sigue frágil y mi espíritu se siente abatido. En mi dolor, recuerdo cómo dijiste: "Bástate mi gracia; porque mi poder se perfecciona en la debilidad." Pero ahora, Señor, mi debilidad se siente abrumadora, y anhelo ver Tu poder obrando en mi vida.

Dios, confieso mi frustración y mi duda. Siento que estás en silencio, y me encuentro en este valle sin un camino claro hacia adelante. Ayúdame a confiar en que estás aquí conmigo, incluso cuando no puedo ver la evidencia de Tu presencia. Enséñame a apoyarme en Tus promesas de que nunca me dejarás ni me desampararás, incluso en los momentos más oscuros.

Fortalece mi espíritu, Padre, para soportar con paciencia y esperanza. Permíteme encontrar consuelo en Tu amor, un amor que nunca falla, y ayúdame a aferrarme a la creencia de que estás obrando todas las cosas para mi bien, aunque no pueda entender Tus caminos. Renueva mi fe, Señor, y concédeme la paz que sobrepasa todo entendimiento. Amén.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-mental-health', 'es', 'title', 'Una Oración por Tu Salud Mental');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-mental-health', 'es', 'description', 'Depresión, ansiedad, entumecimiento. Dios te ve en el pozo. Una oración desde las profundidades.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-mental-health', 'es', 'transcript', '# Una Oración por Tu Salud Mental

Dios, vengo a Ti porque mi mente se siente como una tormenta que no puedo calmar. La oscuridad me envuelve, y es difícil ver una salida. Tú conoces mis pensamientos, incluso cuando corren y se descontrolan. Dices en Tu Palabra que estás cerca de los quebrantados de corazón y salvas a los abatidos de espíritu. Me aferro a esa promesa, Señor, porque me siento aplastado bajo el peso de mi propia mente.

Te pido por Tu paz, la paz que sobrepasa todo entendimiento, para que guarde mi corazón y mi mente. Necesito que Tu luz atraviese esta niebla. Ayúdame a recordar que no estoy solo, que incluso en las profundidades, Tu mano está allí para guiarme. Reafírmame de Tu presencia cuando todo lo demás se siente incierto.

Padre, concédeme la fuerza para pedir ayuda, para hablar de las cosas indecibles que me atormentan. Dame el valor para enfrentar cada día, incluso cuando me siento entumecido y desconectado. Tú eres mi refugio y mi fortaleza, una ayuda siempre presente en las dificultades. Permíteme encontrar descanso en Ti, Señor, cuando mi alma está cansada. Sana mi mente, restaura mi espíritu y renueva mi esperanza. Amén.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-courage-to-act', 'es', 'title', 'Valor para Actuar');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-courage-to-act', 'es', 'description', 'Sabes qué hacer pero el miedo te detiene. Una oración por santa valentía.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-courage-to-act', 'es', 'transcript', '# Valor para Actuar

Señor, vengo ante Ti sintiendo el peso del miedo que me impide avanzar en el camino que has trazado para mí. Conoces mi corazón y las batallas que enfrento dentro de mí. Siento el llamado de Tu voz, pero las sombras de la duda se ciernen grandes. Ayúdame, Dios, a confiar en Tu promesa de que nunca me dejarás ni me desampararás. Has dicho: "Esfuérzate y sé valiente; no temas ni desmayes, porque el Señor tu Dios estará contigo dondequiera que vayas." Padre, me aferro a esta promesa mientras me encuentro en la encrucijada de la decisión.

Dame la fuerza para actuar, incluso cuando mi corazón tiemble. Llena mi ser con el valor que proviene de saber que Tú eres mi refugio y fortaleza, un socorro siempre presente en las dificultades. Cuando mis rodillas se debilitan y mi espíritu flaquea, recuérdame que Tu poder se perfecciona en mi debilidad. Te pido la valentía para avanzar, confiando en que me has preparado para este momento. Dejo mis miedos a Tus pies, Señor, y pido que Tu paz guarde mi corazón y mi mente. Gracias por ser mi guía constante y protector. Amén.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-facing-giants', 'es', 'title', 'Enfrentando a tus Gigantes');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-facing-giants', 'es', 'description', 'El problema es más grande que tú. Bien — eso significa que Dios recibe la gloria.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-facing-giants', 'es', 'transcript', '# Enfrentando a tus Gigantes

Dios, me siento tan pequeño frente a este desafío enorme. Se cierne sobre mí como un gigante, y confieso que el miedo aprieta mi corazón. Sin embargo, recuerdo la historia de David y Goliat, cómo Tú entregaste la victoria a través de un joven pastor con nada más que una honda y fe. Sé que lo que parece imposible para mí es posible contigo. Tú eres mi fuerza y mi escudo; en Ti confía mi corazón, y soy ayudado. Cuando soy débil, Tú eres fuerte, y Tu poder se perfecciona en mi debilidad.

Señor, dame el valor para mantenerme firme, sabiendo que la batalla es Tuya. Ayúdame a dejar a un lado mis dudas y preocupaciones, porque no me has dado un espíritu de temor, sino de poder, amor y dominio propio. Necesito que Tu paz inunde mi alma, calmando la tormenta dentro de mí. Recuérdame que nunca estoy solo, porque Tú estás conmigo, Tu vara y Tu cayado me infunden aliento.

Permíteme ver este desafío como una oportunidad para que Tu gloria brille. Usa mi pequeñez para magnificar Tu grandeza. Enséñame a apoyarme en Tu entendimiento y no en el mío, confiando en que estás obrando todas las cosas para mi bien. Concédeme la valentía para enfrentar a mis gigantes, sabiendo que nada puede separarme de Tu amor. Amén.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-standing-alone', 'es', 'title', 'Permanecer Solo');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-standing-alone', 'es', 'description', 'Todos los demás cedieron. Eres el único que queda en pie. Una oración para los que están en minoría.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-standing-alone', 'es', 'transcript', '# Permanecer Solo

Dios, siento que estoy en una isla solitaria, rodeado por un mar de voces que me dicen que me doblegue y me rompa. Soy el último que permanece firme, y el peso de esta soledad presiona fuertemente sobre mi corazón. Tú prometes que me sostendrás con Tu mano derecha de justicia, tal como dijiste en Isaías 41:10. Me aferro a esa promesa ahora, creyendo que Tu fuerza se perfecciona en mi debilidad. Siento el miedo acercarse, las dudas susurrando que debería rendirme, pero miro a Ti en busca de valor, por el poder de permanecer firme. Conoces las luchas que enfrento, los momentos en que la presión se siente insoportable, sin embargo, confío en que Tú estás conmigo, incluso en esto. Envuélveme en Tu paz que sobrepasa todo entendimiento, porque no puedo permanecer solo sin Ti. Lléname con la valentía para hablar Tu verdad con amor y para permanecer inquebrantable ante las olas de compromiso. Que Tu espíritu me empodere para ser una luz en esta oscuridad. Amén.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-endurance', 'es', 'title', 'Oración por Resistencia');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-endurance', 'es', 'description', 'La carrera es larga y tus piernas están pesadas. Una oración para seguir adelante.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-endurance', 'es', 'transcript', '# Oración por Resistencia

Oh Señor, mi fuerza se siente agotada y el camino por delante parece interminable. En este momento de cansancio, me vuelvo a Ti, mi refugio y mi fortaleza. Has prometido que los que esperan en Ti renovarán sus fuerzas, y me aferro a esta promesa. Ayúdame a correr y no cansarme, a caminar y no desmayar. Mi corazón está cargado de dudas y mis piernas de fatiga, sin embargo, sé que a través de Ti, puedo hacer todas las cosas. Padre, cuando el camino parece imposible, recuérdame que Tú eres la fuente de mi resistencia y valor. Tu Palabra me dice que Tu poder se perfecciona en la debilidad, y así pongo mis debilidades ante Ti, confiando en Tu poderosa fuerza para llevarme adelante. Levanta mi espíritu con la seguridad de que estás conmigo, en cada paso del camino. Que Tu amor inquebrantable sea el viento bajo mis alas, impulsándome hacia adelante cuando siento que no puedo más. Gracias por ser mi roca, mi ayuda siempre presente en tiempos de dificultad. Amén.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-armor-up', 'es', 'title', 'Ponte la Armadura');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-armor-up', 'es', 'description', 'Ponte toda la armadura de Dios. Una oración antes de entrar en batalla.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-armor-up', 'es', 'transcript', '# Ponte la Armadura

Señor, vengo ante Ti sintiendo el peso de las batallas que se avecinan. El miedo y la incertidumbre intentan apoderarse de mí, pero me aferro a Tu promesa de que Tú eres mi refugio y fortaleza, una ayuda siempre presente en tiempos de dificultad. Equípame, Dios, con Tu armadura completa para que pueda mantenerme firme contra las artimañas del enemigo.

Cíñeme con Tu verdad, para que pueda caminar con integridad y claridad en este mundo de confusión. Guarda mi corazón con Tu justicia, porque solo a través de Tu pureza puedo resistir la tentación y mantenerme erguido. Prepara mis pies con el apresto del evangelio de la paz, para que pueda avanzar con confianza y calma, difundiendo Tu amor en cada paso.

Protégeme con la fe, oh Señor, para apagar todas las flechas encendidas de duda y miedo que el enemigo lanza hacia mí. Protege mi mente con el yelmo de la salvación, recordándome que soy Tuyo, salvo por gracia, y nada puede separarme de Tu amor.

Coloca en mi mano la espada del Espíritu, Tu Palabra viva, más cortante que cualquier espada de dos filos, capaz de cortar a través de mentiras y oscuridad. Al entrar en la refriega, recuérdame que no estoy solo, porque Tú, mi Dios, vas delante de mí, detrás de mí y a mi lado. Con valentía y fuerza extraídas de Ti, enfrento este día. Amén.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-forgiving-others', 'es', 'title', 'Perdonar a Alguien que te Ha Herido');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-forgiving-others', 'es', 'description', 'No lo merecen. Tampoco tú lo merecías. Una oración para liberar la amargura.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-forgiving-others', 'es', 'transcript', '# Perdonar a Alguien que te Ha Herido

Oh Señor, estoy luchando con sentimientos de dolor y resentimiento. Tú conoces el dolor que se me ha infligido y lo difícil que ha sido dejarlo ir. Confieso que mi corazón está cargado de amargura, y anhelo la liberación que viene del perdón. Recuerdo Tus palabras, "Perdonaos unos a otros, como Dios os perdonó a vosotros en Cristo," y quiero seguir Tu ejemplo, pero se siente tan difícil.

Padre, por favor ayúdame a ver más allá del dolor y a mirar el corazón de la persona que me ha hecho daño. Sé que ellos también son humanos y falibles, al igual que yo. Recuérdame la gracia y misericordia que me has mostrado innumerables veces, incluso cuando no lo merecía. Tu amor no tiene límites, y quiero que mi corazón refleje ese mismo amor.

Te pido la fuerza para perdonar, no desde mi propia capacidad, sino desde la abundancia de Tu Espíritu dentro de mí. Sana mis heridas, Señor, y reemplaza mi amargura con paz. Ayúdame a liberar esta carga en Tus manos, confiando en que Tú eres el sanador y juez supremo. Que Tu amor me inunde, renovando mi espíritu y liberándome de las cadenas del resentimiento.

Gracias por Tu paciencia conmigo, Dios. Amén.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-asking-forgiveness', 'es', 'title', 'Pidiendo Perdón a Dios');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-asking-forgiveness', 'es', 'description', 'Lo arruinaste. En grande. Pero la misericordia de Dios es más grande que tu desastre.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-asking-forgiveness', 'es', 'transcript', '# Pidiendo Perdón a Dios

Oh Señor, vengo ante Ti con un corazón pesado, sabiendo que me he desviado de Tu camino. He cometido errores, y siento el peso de mis acciones sobre mí. Padre, lamento las formas en que he lastimado a otros y a mí mismo. Sé que no puedo deshacer lo que está hecho, pero te pido Tu perdón, confiando en Tu infinita misericordia.

Dijiste en Tu Palabra que si confesamos nuestros pecados, Tú eres fiel y justo para perdonarnos y limpiarnos de toda maldad. Me aferro a esa promesa ahora, Señor, esperando que Tu gracia me lave. Anhelo un nuevo comienzo, una oportunidad para ser íntegro de nuevo a Tus ojos. Por favor, Señor, ayúdame a apartarme de mis malos caminos y a caminar en rectitud.

Me siento tan débil, Padre, y necesito Tu fuerza para guiarme. Enséñame a perdonarme a mí mismo como Tú me perdonas, y concédeme el valor para enmendar donde pueda. Que Tu amor llene los lugares rotos en mi corazón y me guíe hacia la sanación y la reconciliación. Señor, estoy agradecido por Tu amor inquebrantable que cubre incluso mis fallos más profundos. Gracias por ser mi refugio y mi redentor. Amén.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-forgiving-yourself', 'es', 'title', 'Perdonarte a Ti Mismo');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-forgiving-yourself', 'es', 'description', 'Dios te perdonó. ¿Por qué no puedes tú? Una oración para dejar de cargar con lo que ya está pagado.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-forgiving-yourself', 'es', 'transcript', '# Perdonarte a Ti Mismo

Señor, vengo ante Ti con un corazón cargado por mi propia incapacidad de perdonarme a mí mismo. Tú conoces mi corazón, y ves cómo me aferro a mis errores pasados, incluso cuando Tú ya los has lavado. Nos dices en Tu Palabra que si confesamos nuestros pecados, Tú eres fiel y justo para perdonarnos y limpiarnos de toda maldad. Sin embargo, Señor, lucho por dejar mi culpa a Tus pies. Ayúdame, Padre, a aceptar la gracia que tan generosamente ofreces.

Sé que aferrarme a esta culpa es como cuestionar el poder de Tu sacrificio. Quiero creer que Tu misericordia es suficiente, que Tu amor cubre incluso las partes más oscuras de mí. Ayúdame a liberar esta carga, a dejar de castigarme por lo que Tú ya has perdonado. Anhelo caminar en la libertad que prometes, abrazar la nueva vida que me has dado.

Señor, enséñame a verme a mí mismo a través de Tus ojos, a entender que soy una nueva creación en Cristo. Ayúdame a soltar las cadenas que me he puesto, a confiar en Tu perfecto plan para mi vida.

Gracias por Tu amor inquebrantable y por el perdón que ofreces, que tan desesperadamente necesito. Guíame para perdonarme a mí mismo como Tú me has perdonado. Amén.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-broken-relationship', 'es', 'title', 'Una Relación Rota');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-broken-relationship', 'es', 'description', 'El puente quemado. ¿Puede ser reconstruido? Una oración por lo que parece irreparable.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-broken-relationship', 'es', 'transcript', '# Una Relación Rota

Padre, vengo ante Ti con un corazón pesado, sabiendo el daño que se ha hecho. El puente entre nosotros está en ruinas, y siento el peso de la ruptura presionando sobre mi alma. Confieso mi parte en esta fractura, porque mis palabras y acciones no siempre han reflejado Tu amor. Anhelo la restauración, pero parece tan fuera de mi alcance. Dios, recuerdo que Tú eres el Dios que reconcilia, el que repara lo que parece imposible de reparar. Colosenses me dice que perdone como Tú me has perdonado, pero mi corazón lucha por liberar el dolor y la ira. Ayúdame a encarnar Tu gracia, incluso cuando siento que estoy entregando una parte de mí mismo. Señor, suaviza nuestros corazones, el mío y el de ellos, para permitir que Tu paz se filtre en las grietas de nuestro dolor. Muéstrame los pasos que necesito dar, las palabras que necesito decir, y el silencio que debo guardar. Confío en Tu poder para sanar y restaurar. Enséñame a ser paciente mientras espero Tu tiempo perfecto. Amén.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-letting-go-anger', 'es', 'title', 'Dejando Ir la Ira');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-letting-go-anger', 'es', 'description', 'La ira se siente justificada. Pero te está consumiendo por dentro. Una oración para liberarla.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-letting-go-anger', 'es', 'transcript', '# Dejando Ir la Ira

Dios, vengo a Ti con un corazón pesado y cargado de ira. Esta ira, se siente tan justificada, sin embargo, sé que me consume desde dentro, devorando lentamente mi paz. Confieso, Señor, que aferrarme a esta ira me ha dado una sensación de control, pero es una falsa libertad que me ata más cada día. Me recuerdas en Efesios 4:31 que debo desechar toda amargura, enojo e ira, y anhelo hacer esto, aunque me parece imposible por mí mismo.

Ayúdame, Padre, a soltar este agarre. Estoy cansado de llevar esta carga y la dejo a Tus pies. Muéstrame cómo perdonar a aquellos que me han hecho daño, incluso cuando mi corazón se resiste. Transforma mi corazón con Tu amor, para que pueda ver a los demás como Tú los ves, imperfectos pero amados. Pido Tu fortaleza para elegir el perdón diariamente, incluso cuando parece lo más difícil de hacer.

Llena mi ser con Tu paz, Señor, la paz que sobrepasa todo entendimiento, y reemplaza mi ira con Tu compasión y gracia. Confío en que al rendir esto a Ti, encontraré la libertad que mi alma busca desesperadamente. Gracias por Tu paciencia y por guiarme hacia la sanación. Amén.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-marriage', 'es', 'title', 'Oración por Tu Matrimonio');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-marriage', 'es', 'description', 'El amor es una elección diaria. Una oración por paciencia, gracia y mantenerse comprometido.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-marriage', 'es', 'transcript', '# Oración por Tu Matrimonio

Padre Celestial, vengo ante Ti con un corazón que busca Tu guía y fortaleza en mi matrimonio. Sé que el amor es más que un sentimiento, es una elección que hacemos cada día. Por favor, ayúdame a elegir el amor, incluso en los momentos en que se siente difícil. Recuérdame la paciencia y la gracia que me muestras, para que pueda extender lo mismo a mi cónyuge.

Señor, te pido la sabiduría para entender y apreciar el don del matrimonio. Enséñame a ser pronto para oír, tardo para hablar y tardo para airarme, tal como Tu palabra instruye en Santiago 1:19. Ayúdame a comunicarme con amabilidad y respeto, incluso en el desacuerdo. Que mis palabras edifiquen, en lugar de destruir, y que sean un reflejo de Tu amor.

Dios, oro por la fuerza para permanecer comprometido, para aferrarme a las promesas que hicimos ante Ti. Cuando surjan desafíos, ayúdanos a volvernos el uno hacia el otro en lugar de alejarnos. Muéstranos cómo apoyarnos en Ti juntos, buscando Tu voluntad por encima de nuestros propios deseos.

Padre, protege nuestro matrimonio de influencias externas que puedan buscar dividirnos. Rodéanos de personas que animen y apoyen nuestra unión, y mantén nuestros corazones enfocados en Ti como el fundamento de nuestra relación.

Que nuestro amor mutuo sea un testimonio de Tu amor por nosotros, creciendo más profundo y más fuerte con cada día que pasa. Amén.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-children', 'es', 'title', 'Oración por Tus Hijos');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-children', 'es', 'description', 'No puedes protegerlos de todo. Pero puedes cubrirlos con oración.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-children', 'es', 'transcript', '# Oración por Tus Hijos

Padre Celestial, vengo ante Ti con un corazón lleno de amor y preocupación por mis hijos. Tú conoces la profundidad de mis esperanzas y temores por ellos. Te pido que seas su escudo y protector. En un mundo lleno de incertidumbre, guía sus pasos y guarda sus corazones. Reconozco que no puedo protegerlos de cada tormenta, pero los confío en Tus poderosas manos, creyendo que Tú eres su refugio.

Señor, Tu Palabra dice: "Instruye al niño en su camino, y aun cuando fuere viejo no se apartará de él." Ayúdame a guiarlos con sabiduría y amor, plantando semillas de fe que crezcan fuertes en sus corazones. Dame la paciencia y el entendimiento para nutrir sus dones únicos y ser un ejemplo viviente de Tu gracia.

Padre, cuando me sienta abrumado por la responsabilidad de ser padre, recuérdame que Tú estás conmigo. Concédeme paz en momentos de preocupación y fuerza cuando me sienta cansado. Ayúdame a liberar mis ansiedades a Ti, confiando en que Tú amas a mis hijos incluso más de lo que yo los amo.

Rodea a mis hijos con Tus ángeles, Señor, y llena sus vidas con Tu presencia. Que crezcan para conocerte profundamente y confiar en Tu amor inquebrantable. Amén.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-parents', 'es', 'title', 'Honrar a Tus Padres');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-parents', 'es', 'description', 'No son perfectos. Tú tampoco lo eres. Una oración por gratitud y gracia.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-parents', 'es', 'transcript', '# Honrar a Tus Padres

Querido Dios, vengo ante Ti con un corazón lleno de gratitud y lucha. Has puesto a mis padres en mi vida como aquellos que me guiaron y cuidaron. Estoy agradecido por sus sacrificios, por el amor que me han mostrado de maneras que a menudo paso por alto o doy por sentado. Sin embargo, Señor, admito que a veces me resulta difícil honrarlos como Tú mandas. No son perfectos, ni yo, y a veces nuestras imperfecciones chocan.

Ayúdame a verlos a través de Tus ojos, con compasión y comprensión. Enséñame a extenderles gracia, incluso cuando es difícil, y a expresar mi gratitud más libremente. Tu palabra me recuerda: "Honra a tu padre y a tu madre," y anhelo vivir esto, incluso cuando es un desafío.

Guía mis palabras y acciones, Señor, para que reflejen el amor y respeto que tengo por ellos. Ayúdame a perdonar heridas y malentendidos pasados, a dejar ir la amargura, y a construir un puente de amor que Te honre. En momentos de frustración, lléname de Tu paz y paciencia.

Gracias por mi familia, Dios, y por las lecciones que me enseñas a través de ellos. Que nuestra relación sea un testimonio de Tu amor y gracia. Amén.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-lonely', 'es', 'title', 'Cuando Te Sientes Solo');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-lonely', 'es', 'description', 'Nadie llama. Nadie ve. Pero Dios sí. Una oración para los solitarios.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-lonely', 'es', 'transcript', '# Cuando Te Sientes Solo

Oh Señor, vengo a Ti con un corazón pesado, sintiendo el peso de la soledad presionando sobre mí. En este espacio silencioso donde mi teléfono no suena y mi puerta permanece cerrada, me recuerda cuánto necesito Tu presencia. Padre, conoces mis pensamientos y mis miedos, y ves las lágrimas que caen cuando nadie está mirando. Prometes en el Salmo 34:18 que estás cerca de los quebrantados de corazón y salvas a los de espíritu abatido. Me aferro a esta verdad, sabiendo que incluso en mi soledad, nunca estoy realmente solo contigo a mi lado.

Dios, ayúdame a ver las conexiones que tengo, las amistades que pueden estar distantes pero aún son reales. Abre mis ojos a nuevas oportunidades de comunidad y compañerismo. Concédeme el valor para acercarme cuando me sienta aislado, y la fortaleza para aceptar el amor que otros ofrecen. Enséñame paciencia y confianza en Tu perfecto tiempo, sabiendo que Tus planes para mí son para bien, para darme esperanza y un futuro.

Que Tu amor llene los espacios vacíos dentro de mí, Señor. Recuérdame que soy visto, conocido y amado por Ti. Gracias por ser mi constante compañero, mi refugio y mi fortaleza. Amén.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-toxic-people', 'es', 'title', 'Tratando con Personas Difíciles');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-toxic-people', 'es', 'description', 'Te agotan. Una oración por límites, sabiduría y no perder la cordura.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-toxic-people', 'es', 'transcript', '# Tratando con Personas Difíciles

Señor, vengo a Ti sintiéndome cansado y estirado por aquellos que me rodean. Algunas relaciones en mi vida parecen drenar la energía y la paz que Tú me has dado. Necesito Tu sabiduría, Señor, para navegar estas interacciones desafiantes. Tu palabra me dice que ame a mi prójimo como a mí mismo, pero a veces es tan difícil hacerlo. Por favor, ayúdame a establecer límites saludables que honren tanto a Ti como a la persona que estás moldeando en mí. Concédeme paciencia y comprensión cuando mi corazón siente que se está quedando vacío.

En momentos en que quiero reaccionar con frustración, recuérdame Tu llamado a ser pronto para escuchar, tardo para hablar y tardo para enojarse. Llena mi corazón de compasión que refleje la Tuya, incluso cuando sea difícil. Ayúdame a ver a estas personas a través de Tus ojos, con gracia y misericordia. Señor, dame la fuerza para mantenerme firme en mis límites, para proteger mi propio corazón mientras sigo extendiendo bondad y amor.

Guíame, Padre, a encontrar maneras de ser un pacificador sin perderme en el proceso. Confío en que Tú puedes transformar estas relaciones difíciles en reflejos de Tu amor y gracia. Gracias por caminar conmigo a través de la tensión. Amén.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-financial-provision', 'es', 'title', 'Oración por Provisión');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-financial-provision', 'es', 'description', 'Las facturas están por vencer. La cuenta está vacía. Una oración por el suministro sobrenatural de Dios.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-financial-provision', 'es', 'transcript', '# Oración por Provisión

Querido Señor, vengo ante Ti con el corazón cargado por el peso de las cargas financieras. Tú conoces las facturas que están por vencer y la vacuidad de mi cuenta bancaria. Me siento tan abrumado y ansioso sobre cómo voy a llegar a fin de mes. Padre, recuerdo Tu promesa en Filipenses 4:19, que suplirás todas mis necesidades conforme a Tus riquezas en gloria en Cristo Jesús. Ayúdame a confiar en esa promesa, incluso cuando mis circunstancias parecen insuperables.

Deposito mis miedos y preocupaciones a Tus pies, Señor, y pido Tu provisión sobrenatural. Tú eres el Dios que alimentó a las multitudes con solo unos pocos panes y peces, y creo que también puedes multiplicar mis recursos. Por favor, guíame con sabiduría para manejar lo que tengo con gracia y discernimiento. Muéstrame oportunidades que quizás no vea y abre puertas que parecen firmemente cerradas.

En este momento de necesidad, recuérdame que mi valor no está ligado a mi riqueza y que Tú eres mi proveedor supremo. Fortalece mi fe, para que pueda permanecer firme, sabiendo que tienes mi futuro en Tus manos. Que pueda encontrar paz en Tu presencia, incluso en medio de tormentas financieras. Gracias por escuchar mis clamores y por Tu amor inquebrantable. Amén.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-debt', 'es', 'title', 'Libertad de Deudas');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-debt', 'es', 'description', 'El peso de lo que debes. Una oración por sabiduría, disciplina y avance.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-debt', 'es', 'transcript', '# Libertad de Deudas

Querido Dios, vengo a Ti con un corazón pesado, agobiado por el peso de mis luchas financieras. Siento que me estoy ahogando en deudas y no sé cómo encontrar la salida. Necesito Tu sabiduría, Señor, para tomar las decisiones correctas con lo poco que tengo. Tú dices en Proverbios que "el que toma prestado es siervo del que presta," y me siento esclavizado ahora, incapaz de encontrar paz. Por favor, guíame hacia la libertad financiera.

Te pido disciplina, Padre, para manejar mis recursos sabiamente. Ayúdame a resistir la tentación de gastar en lo que no necesito, y en cambio, a ser un buen administrador de las bendiciones que me has dado. Enséñame paciencia y perseverancia, incluso cuando el camino por delante parezca largo e incierto.

Señor, oro por avances en mi situación financiera. Abre puertas de oportunidad que no puedo ver y provee para mis necesidades de maneras inesperadas. Recuérdame, Dios, que Tu gracia es suficiente y que no estoy solo en esta lucha. Dame el valor para confiar en Tu provisión y la fe para creer que me llevarás a un lugar de estabilidad y paz.

Amén.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-generosity', 'es', 'title', 'Un Corazón de Generosidad');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-generosity', 'es', 'description', 'Manos abiertas, no puños cerrados. Una oración para dar libremente y confiar en Dios para más.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-generosity', 'es', 'transcript', '# Un Corazón de Generosidad

Querido Dios, vengo a Ti con un corazón agobiado por el estrés financiero. Siento el agarre del miedo apretándose a mi alrededor, y es difícil ver más allá de mis necesidades inmediatas. Sin embargo, me recuerda Tu promesa, que suplirás todas mis necesidades conforme a Tus riquezas en gloria (Filipenses 4:19). Quiero confiar en esa promesa, Señor, pero necesito Tu ayuda para dejar ir mi ansiedad y abrir mis manos.

Enséñame a tener un corazón de generosidad, incluso cuando siento que tengo poco para dar. Ayúdame a recordar que el óbolo de la viuda fue precioso a Tus ojos, no por su valor, sino por su confianza en Ti. Que mi dar, sin importar cuán pequeño sea, sea un acto de fe en lugar de una fuente de estrés.

Señor, concédeme la sabiduría para administrar lo que me has confiado, y el valor para dar libremente, sabiendo que Tú eres mi proveedor. Cuando me sienta tentado a retener, recuérdame que nunca podré darte más de lo que Tú me das. Llena mi corazón de paz, y que mi confianza en Ti reemplace mis miedos. Que mi enfoque cambie de la escasez a la abundancia en Tu amor, y que encuentre gozo en dar, sabiendo que mi verdadero tesoro está en el cielo.

Amén.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-contentment', 'es', 'title', 'Oración por la Satisfacción');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-contentment', 'es', 'description', 'Basta es suficiente. Una oración para dejar de perseguir y comenzar a descansar en lo que tienes.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-contentment', 'es', 'transcript', '# Oración por la Satisfacción

Padre Celestial, vengo a Ti con un corazón agobiado por el estrés financiero. El peso de mis preocupaciones se ha vuelto demasiado para soportar. Me siento atrapado en un ciclo de querer y necesitar más, pero nunca encontrando paz. Señor, Tú conoces mis necesidades antes de que siquiera las mencione. Siempre has provisto para mí, incluso cuando no noté Tu mano en acción. Ayúdame a confiar en Tu provisión y a recordar que "la piedad acompañada de contentamiento es gran ganancia" (1 Timoteo 6:6).

Padre, guía mi corazón lejos de la búsqueda interminable de más, y enséñame a descansar en el momento presente. Abre mis ojos a las bendiciones que ya me rodean, y ayúdame a encontrar gozo en lo simple y lo pequeño. Anhelo soltar mi agarre de las cosas de este mundo y aferrarme a Ti en su lugar. Por favor, concédeme la sabiduría para manejar lo que tengo con gratitud y fidelidad.

Señor, recuérdame que la verdadera riqueza no se encuentra en la abundancia, sino en Tu presencia. Que busque primero Tu reino, confiando en que todo lo demás será dado conforme a Tu perfecta voluntad. Gracias por ser mi refugio y mi fortaleza, una ayuda constante en tiempos de dificultad. Amén.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-job-work', 'es', 'title', 'Oración por Tu Trabajo');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-job-work', 'es', 'description', 'Temor de lunes o confusión profesional. Una oración por propósito y dirección en tu trabajo.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-job-work', 'es', 'transcript', '# Oración por Tu Trabajo

Señor, vengo ante Ti sintiéndome abrumado por las cargas de mi trabajo. Los lunes traen consigo un peso que no puedo sacudirme, y a menudo me siento perdido en el caos de mi carrera. Te pido Tu guía y sabiduría, porque Tú conoces los planes que tienes para mí, planes de bienestar y no de calamidad, para darme un futuro y una esperanza. Ayúdame a confiar en que me estás guiando, incluso cuando no puedo ver el camino con claridad.

Anhelo propósito y dirección, claridad en medio de la confusión. Muéstrame cómo usar los talentos que me has dado para Tu gloria. Abre puertas que no puedo ver y cierra aquellas que me alejan de Tu voluntad. Llena mi corazón con el deseo de hacer mi trabajo como si estuviera trabajando para Ti, no para amos humanos. Dame la fuerza para enfrentar cada día con valentía y fe.

Señor, cuando sienta que el temor se acerca, recuérdame que Tú estás conmigo, que no estoy solo. Ayúdame a encontrar alegría en las pequeñas victorias y a confiar en que estás obrando todo para mi bien. Pongo mi carrera, mis sueños y mis miedos en Tus manos, sabiendo que Tú eres el proveedor y protector supremo.

Gracias por ser mi guía y mi roca. Amén.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-new-day', 'es', 'title', 'Un Nuevo Día');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-new-day', 'es', 'description', 'Misericordias frescas. Borrón y cuenta nueva. Una oración para comenzar con intención y gratitud.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-new-day', 'es', 'transcript', '# Un Nuevo Día

Señor, al romper el alba y comenzar un nuevo día, vengo ante Ti con un corazón lleno de gratitud. Gracias por el aliento en mis pulmones y la promesa de misericordias frescas. Tu fidelidad es nueva cada mañana, y me recuerda Tu amor inagotable. Hoy, te pido guía en cada paso que doy. Que mis palabras reflejen Tu verdad y mis acciones estén llenas de Tu gracia.

Padre, Tú conoces los desafíos que puedo enfrentar y las decisiones que debo tomar. Concédeme sabiduría y discernimiento, para que pueda caminar de una manera que Te honre. Mientras llevo las cargas de ayer, las pongo a Tus pies, confiando en que Tú haces nuevas todas las cosas. Tu palabra dice que Tus misericordias son nuevas cada mañana, y en esta promesa encuentro esperanza y fortaleza.

Ayúdame a ver a los demás a través de Tus ojos, a ser un vaso de Tu amor y paz. Que sea pronto para escuchar, lento para hablar y lento para la ira, brillando Tu luz en cada rincón de mi vida. Gracias por este nuevo día y la oportunidad de comenzar de nuevo. Guíame, Señor, y que Tu presencia sea mi consuelo. Amén.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-surrender-day', 'es', 'title', 'Entregando Este Día');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-surrender-day', 'es', 'description', 'Antes de que la lista de tareas se apodere — entrega el día a Dios primero.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-surrender-day', 'es', 'transcript', '# Entregando Este Día

Señor, al salir el sol, vengo a Ti con un corazón ansioso pero a veces cansado. Pongo este día ante Ti, reconociendo que sin Tu guía, mis pasos vacilan. Tu palabra me recuerda que "Tus misericordias son nuevas cada mañana" y estoy agradecido por el nuevo comienzo que ofreces. Hoy, entrego mis planes, mis preocupaciones y mis ambiciones a Ti. A menudo me dejo llevar por el ajetreo, olvidando buscar Tu voluntad primero. Ayúdame a priorizarte por encima de todo, confiando en que dirigirás mi camino.

Dame la sabiduría para discernir lo que realmente importa y el valor para dejar ir lo que no. Equípame con paciencia y amabilidad en mis interacciones, para que pueda reflejar Tu amor a aquellos que encuentro. Cuando surjan desafíos, recuérdame de Tu fuerza dentro de mí, porque sin Ti, nada puedo hacer. Que mis acciones hoy sean un testimonio de Tu bondad, y que mis palabras traigan paz y aliento.

Guíame, Señor, en cada momento, y llena mi corazón con una paz que sobrepasa todo entendimiento. Pongo este día enteramente en Tus manos. Amén.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-focus-and-clarity', 'es', 'title', 'Enfoque y Claridad');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-focus-and-clarity', 'es', 'description', 'Una mente clara, un corazón firme. Una oración por sabiduría antes de que comience el caos.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-focus-and-clarity', 'es', 'transcript', '# Enfoque y Claridad

Padre, al romper el alba y desplegarse un nuevo día, vengo a Ti buscando enfoque y claridad. Mi mente a menudo está llena de pensamientos y distracciones, sin embargo, anhelo una quietud que solo Tú puedes proporcionar. Tu palabra me recuerda en Santiago 1:5 que si alguno de nosotros tiene falta de sabiduría, la pida a Ti, que das a todos abundantemente y sin reproche. Así que, Señor, te pido Tu sabiduría hoy. 

Guía mis pensamientos y alinea mis acciones con Tu voluntad. Ayúdame a discernir lo que es esencial y lo que puede dejarse de lado. Mantén mi corazón firme cuando el mundo a mi alrededor sea caótico. Enséñame a encontrar momentos de quietud en medio de la actividad, y que esos momentos estén llenos de Tu presencia. 

Señor, confío en que ya has ido delante de mí, preparando el camino. Ayúdame a caminar con confianza, sabiendo que no estoy solo. Dame ojos para ver las oportunidades que pones delante de mí y la fuerza para perseguirlas con integridad y propósito.

Gracias por el regalo de este nuevo día. Que sea uno en el que refleje Tu amor y gracia en todo lo que haga. Amén.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-gods-presence-today', 'es', 'title', 'La Presencia de Dios Hoy');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-gods-presence-today', 'es', 'description', 'No salgas de casa sin ella. Una oración para llevar la presencia de Dios a cada momento.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-gods-presence-today', 'es', 'transcript', '# La Presencia de Dios Hoy

Padre Celestial, al levantarme para encontrar la luz de un nuevo día, pido que Tu presencia me envuelva. Tú eres mi roca y mi refugio, y necesito Tu fuerza para llevarme a través de lo que hoy pueda deparar. Me recuerda Tu promesa de que donde dos o tres se reúnen en Tu nombre, allí estás Tú con ellos. Aunque ahora solo somos Tú y yo, siento el poder de Tu presencia.

Señor, guía mis pasos y mis pensamientos hoy. Ayúdame a caminar en amor y a ver a los demás como Tú los ves. Cuando surjan desafíos, sé mi paz y mi sabiduría. Que mis acciones reflejen Tu gracia y mis palabras hablen de Tu bondad. Llena mi corazón con el valor para compartir Tu luz en todo lo que hago.

Pongo mis planes a Tus pies, confiando en que Tú dirigirás mi camino. En momentos de duda o miedo, recuérdame que Tú estás conmigo, como prometiste en Isaías, diciendo: "No temas, porque yo estoy contigo; no desmayes, porque yo soy tu Dios." Que esta seguridad sea mi fundamento durante todo el día.

Gracias por el regalo de hoy, por el aliento en mis pulmones y las oportunidades de acercarme más a Ti. Que Tu presencia sea mi compañera constante. Amén.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-purpose-today', 'es', 'title', 'Caminando en Propósito');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-purpose-today', 'es', 'description', 'No solo ocupado — intencional. Una oración para vivir hoy con propósito.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-purpose-today', 'es', 'transcript', '# Caminando en Propósito

Padre Celestial, al romper el alba y comenzar un nuevo día, me presento ante Ti buscando Tu guía. Sé que cada día es un regalo de Ti, lleno de oportunidades para servir y glorificar Tu nombre. Ayúdame a caminar intencionalmente en el propósito que has puesto delante de mí. Tu Palabra me dice que "muchos pensamientos hay en el corazón del hombre; mas el consejo de Jehová permanecerá." Enséñame a alinear mi corazón con Tu voluntad, para que no esté simplemente ocupado, sino intencional en todo lo que hago.

Concédeme sabiduría para discernir las tareas que realmente importan y el valor para dejar de lado las distracciones. Que Tu Espíritu me guíe hacia aquellos que necesitan un toque de Tu amor y bondad hoy. Abre mis ojos para ver las necesidades a mi alrededor y dame la fuerza para satisfacerlas con gracia y humildad.

Padre, confío en que has preparado buenas obras para que yo camine en ellas hoy. Que mis acciones reflejen Tu amor y mis palabras traigan vida y ánimo a quienes encuentro. Al avanzar, que mi vida sea un testimonio de Tu bondad y misericordia. Mantén mi corazón sintonizado con Tu voz y mis pies firmes en el camino que has trazado para mí. Amén.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-end-of-day', 'es', 'title', 'Fin del Día');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-end-of-day', 'es', 'description', 'El día ha terminado. Una oración para soltar lo que sucedió y descansar en el cuidado de Dios.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-end-of-day', 'es', 'transcript', '# Fin del Día

Querido Dios, al llegar el día a su fin, me presento ante Ti con un corazón lleno de gratitud y cansancio. Gracias por los momentos de alegría y la fortaleza para enfrentar los desafíos que encontré. Has sido mi refugio y fortaleza, una ayuda muy presente en las tribulaciones, tal como me recuerda el Salmo 46:1. Pongo ante Ti todos mis éxitos y fracasos, sabiendo que en Tus manos, encuentran un significado más allá de mi comprensión.

Perdóname por las veces que fallé hoy, por las palabras duras dichas con prisa y las oportunidades que perdí para mostrar bondad. Limpia mi corazón, Señor, y renueva un espíritu recto dentro de mí. Me siento humilde ante Tu gracia que me encuentra en mi quebrantamiento y me eleva hacia la sanación.

Mientras me preparo para descansar, pido que Tu paz me envuelva, calmando las tormentas dentro de mí. Guarda mis pensamientos y sueños, para que pueda despertar renovado y listo para servirte de nuevo. Vigila a aquellos que amo, concediéndoles seguridad durante la noche. Confío en que Tus misericordias serán nuevas en la mañana, tal como has prometido.

Gracias, Dios, por ser mi compañero constante en cada momento de este día. Entrego todo en Tu cuidado, creyendo que en Ti, encuentro el verdadero descanso. Amén.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-reflect-and-release', 'es', 'title', 'Reflexiona y Libera');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-reflect-and-release', 'es', 'description', '¿Qué salió bien? ¿Qué no? Devuélvelo todo. Mañana es un nuevo comienzo.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-reflect-and-release', 'es', 'transcript', '# Reflexiona y Libera

Dios, al llegar el final del día, vengo ante Ti con un corazón lleno de gratitud y reflexión. Gracias por los momentos de alegría y paz que llenaron este día. Tu fidelidad ha sido mi ancla, y Tus misericordias han sido nuevas cada mañana, tal como prometiste en Lamentaciones 3:22-23. Estoy agradecido por la fuerza que me diste para enfrentar los desafíos y por la gracia que me sostuvo a través de ellos.

Padre, hubo momentos hoy en los que fallé, cuando mis palabras o acciones no reflejaron Tu amor. Las pongo a Tus pies, buscando Tu perdón y guía. Ayúdame a aprender de estos momentos y a confiar en Tu capacidad para transformar mis debilidades en fortalezas.

Mientras me preparo para descansar, libero las cargas y preocupaciones que se aferran a mi corazón. Las confío a Ti, sabiendo que Te preocupas profundamente por mí. Concédeme la paz que sobrepasa todo entendimiento, y que mis pensamientos se centren en lo que es verdadero y noble.

Gracias por ser mi refugio y fortaleza. Que Tu presencia me envuelva durante la noche, y que mañana sea un nuevo comienzo lleno de oportunidades para caminar más cerca de Ti. Amén.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-gratitude-tonight', 'es', 'title', 'Gratitud Esta Noche');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-gratitude-tonight', 'es', 'description', 'Antes de que tu cabeza toque la almohada — nombra tres cosas buenas. Agradece al Dador.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-gratitude-tonight', 'es', 'transcript', '# Gratitud Esta Noche

Querido Dios, al acostarme para descansar, vengo a Ti con un corazón lleno de gratitud. Gracias por el regalo de este día, por los momentos de alegría y las lecciones aprendidas a través de los desafíos. Estoy agradecido por el calor y el refugio de mi hogar, un lugar de paz donde puedo retirarme y encontrar consuelo. Gracias por los seres queridos que has colocado en mi vida, cuya presencia me recuerda Tu amor y cuidado.

Hoy, experimenté la bondad de un extraño, un recordatorio de que Tu bondad fluye a través de canales inesperados. Gracias por la fortaleza en mi cuerpo que me permitió cumplir con mis deberes y por la claridad de mente que guió mis decisiones. Estoy agradecido por la belleza de la creación que me rodeó, un testimonio de Tus maravillosas obras.

Al reflexionar sobre estos dones, recuerdo las palabras del Salmista: "Jehová es mi pastor; nada me faltará." Tu provisión es abundante y Tu gracia es suficiente. Incluso en momentos de preocupación, Tú provees. Al cerrar mis ojos esta noche, llena mis sueños de paz y mi corazón con la seguridad de que Tú sostienes el mañana. Amén.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-protection-through-night', 'es', 'title', 'Protección Durante la Noche');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-protection-through-night', 'es', 'description', 'Ángeles guardianes y la cobertura de Dios. Una oración por seguridad mientras duermes.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-protection-through-night', 'es', 'transcript', '# Protección Durante la Noche

Padre Celestial, al desvanecerse el día y envolvernos la noche, vengo a Ti buscando Tu protección. En la quietud de estas horas, te pido que me cubras con Tus alas, tal como Tu Palabra nos asegura que "Con sus plumas te cubrirá, y debajo de sus alas estarás seguro" (Salmo 91:4). Tú eres mi refugio y mi fortaleza, y pongo mi confianza solo en Ti.

Señor, oro para que Tus ángeles vigilen alrededor de mi hogar esta noche. Que Tu presencia sea un escudo contra cualquier daño que busque perturbar mi descanso. En la quietud de la noche, cuando los miedos y preocupaciones a menudo surgen, recuérdame que Tú estás conmigo, y que nunca duermes ni te adormeces.

Concédeme paz mental, querido Dios, y aquieta los pensamientos acelerados que tienden a invadir a esta hora. Ayúdame a liberar las cargas de este día en Tus manos, confiando en que Tú sostienes el mañana con seguridad. Que Tu paz, que sobrepasa todo entendimiento, guarde mi corazón y mi mente mientras duermo.

Gracias, Señor, por Tu constante vigilancia y amor. Confío en Tu protección durante esta noche y cada noche. Amén.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-tomorrow-in-gods-hands', 'es', 'title', 'El Mañana Está en las Manos de Dios');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-tomorrow-in-gods-hands', 'es', 'description', 'Deja de planificar. Deja de preocuparte. El mañana le pertenece a Él. Una oración para soltar.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-tomorrow-in-gods-hands', 'es', 'transcript', '# El Mañana Está en las Manos de Dios

Señor, al desvanecerse el día en la noche, vengo ante Ti con un corazón lleno de preocupaciones y planes que me agobian. Confieso que a menudo intento tomar las riendas con demasiada fuerza, olvidando que Tú eres quien sostiene el mañana. Tu Palabra me recuerda que no debo preocuparme por el día de mañana, porque el día de mañana traerá su afán. Basta a cada día su propio mal, y sin embargo me encuentro enredado en los qué pasará y los qué puede venir.

Ayúdame, Dios, a soltar mi agarre y confiar en Tu soberanía. Tú, que formaste las estrellas y las nombraste, que conoces el número de cabellos en mi cabeza, seguramente puedes manejar las incertidumbres que me atormentan. Dejo mis planes a Tus pies, sabiendo que Tus pensamientos son más altos que mis pensamientos y Tus caminos más altos que mis caminos.

Concédeme la paz que sobrepasa todo entendimiento, la paz que guarda mi corazón y mi mente en Cristo Jesús. Que descanse en la seguridad de que ya estás en el futuro, obrando todas las cosas para mi bien y Tu gloria. Al cerrar mis ojos esta noche, permíteme encontrar consuelo en Tus promesas y despertar con una fe renovada en Tu cuidado eterno.

Amén.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-lost-someone', 'es', 'title', 'Cuando Has Perdido a Alguien');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-lost-someone', 'es', 'description', 'La silla está vacía. El silencio es ensordecedor. Una oración para el dolor que no se va.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-lost-someone', 'es', 'transcript', '# Cuando Has Perdido a Alguien

Oh Señor, mi corazón está pesado y mi alma duele con el peso de esta pérdida. La silla que una vez sostuvo la risa y el calor ahora está vacía, un recordatorio silencioso de la ausencia que llena cada rincón de mi mundo. Padre, Tú conoces la profundidad de mi dolor, y prometes que estás cerca de los quebrantados de corazón y salvas a los de espíritu abatido. Sin embargo, me siento tan solo en este silencio.

Estoy luchando por encontrar paz en medio del dolor, Señor. Los recuerdos inundan, no solicitados y abrumadores, y no sé cómo seguir adelante sin ellos. Tú eres el Dios de toda consolación, pero en este momento, la consolación se siente distante. Ayúdame a confiar en Tu presencia, incluso cuando parece oculta a mi vista.

Te traigo mis preguntas, mi ira, mis lágrimas. Enséñame a apoyarme en Ti, a sacar fuerzas de Tu promesa de que nunca me dejarás ni me desampararás. Que Tu amor sea el bálsamo que calme este corazón herido. En este valle de sombra de muerte, recuérdame que Tú estás conmigo, guiándome a través de cada día, un paso a la vez. Amén.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-why-god', 'es', 'title', 'Cuando Preguntas ''¿Por Qué?''');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-why-god', 'es', 'description', 'Sin respuestas. Solo dolor. Una oración para cuando Dios parece cruel o ausente.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-why-god', 'es', 'transcript', '# Cuando Preguntas ''¿Por Qué?''

Dios, vengo a Ti con un corazón cargado de dolor, y no entiendo por qué ha sucedido esto. Se siente tan injusto, y lucho por ver Tu bondad en este sufrimiento. Es difícil comprender cómo un Dios amoroso podría permitir tal pérdida. Confieso que me siento abandonado, como si mis clamores no fueran escuchados. Tú prometes en el Salmo 34:18 que estás cerca de los quebrantados de corazón, pero ahora mismo, me siento distante de Ti.

Necesito Tu presencia más que nunca, Señor. Ayúdame a sentirte en medio de esta oscuridad. No sé cómo avanzar ni cómo soportar este vacío doloroso. No tengo las respuestas, y no estoy seguro de si alguna vez las tendré. Todo lo que puedo hacer es acudir a Ti en mi confusión y dolor.

Por favor, Dios, muéstrame que estás aquí. Anhelo Tu consuelo y fortaleza para sostenerme. Déjame sentir Tus brazos envolviéndome, manteniéndome unido cuando siento que me desmorono. A pesar de mis preguntas, ayúdame a confiar en que sigues siendo bueno y soberano, incluso cuando la vida parece tan cruel. Amén.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-broken-dreams', 'es', 'title', 'Lamentando un Sueño Roto');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-broken-dreams', 'es', 'description', 'La vida que planeaste no es la vida que recibiste. Una oración para llorar lo que pudo haber sido.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-broken-dreams', 'es', 'transcript', '# Lamentando un Sueño Roto

Oh Señor, vengo a Ti con un corazón cargado de tristeza, luchando con los fragmentos de sueños que nunca serán. La vida que imaginé parece tan lejana del camino que ahora recorro. Siento el dolor de lo que pudo haber sido, los planes que había trazado con tanto cuidado ahora esparcidos como polvo en el viento. Dios, Tú conoces cada lágrima que derramo, cada grito silencioso de mi espíritu. Me recuerdas a través de Tu palabra que estás cerca de los quebrantados de corazón y salvas a los de espíritu abatido. Me aferro a esa promesa ahora, confiando en que ves mi dolor y lo entiendes completamente.

Confieso, Señor, mi lucha para dejar ir los sueños que sostuve tan fuertemente. Quería que florecieran, que dieran fruto, y sin embargo aquí estoy, sosteniendo solo los restos. Ayúdame a entregar estos sueños a Ti, confiando en que Tus planes son más altos que los míos, incluso cuando se sienten tan distantes e inciertos. Guíame, Señor, mientras navego esta nueva realidad, porque me siento perdido e inseguro de qué pasos tomar. Que Tu amor sea mi consuelo, Tu sabiduría mi guía, mientras lloro lo que pudo haber sido. Enséñame a encontrar esperanza en Tus promesas, a ver belleza en el nuevo camino que tienes para mí. Amén.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-comfort-in-pain', 'es', 'title', 'Consuelo en el Dolor');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-comfort-in-pain', 'es', 'description', 'Dios no siempre lo arregla. Pero se sienta contigo en ello. Una oración por Su presencia.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-comfort-in-pain', 'es', 'transcript', '# Consuelo en el Dolor

Dios, mi corazón está pesado y lleno de tristeza. Vengo a Ti en mi momento de duelo, buscando Tu presencia y consuelo. Conoces las profundidades de mi dolor y las lágrimas que he derramado. Me siento perdido y abrumado, y Te necesito ahora más que nunca. Tu palabra me recuerda que estás cerca de los quebrantados de corazón y salvas a los de espíritu abatido. Me aferro a esa promesa, confiando en que estás cerca, incluso cuando lucho por sentir Tu presencia.

Señor, extraño a quien he perdido, y el dolor parece insoportable a veces. Por favor, envuélveme en Tu amor y dame fuerza para enfrentar cada día. Ayúdame a encontrar momentos de paz en medio del caos, y guíame mientras navego esta nueva realidad sin ellos a mi lado. Sé que Tú lloras conmigo, y estoy agradecido por Tu compasión.

Te pido, Dios, que traigas sanidad a mi corazón. Que Tu luz brille a través de la oscuridad, y ayúdame a apoyarme en Ti cuando mis propias fuerzas fallen. Gracias por caminar este doloroso camino conmigo y por ser mi refugio. Amén.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-hope-after-loss', 'es', 'title', 'Esperanza Después de la Pérdida');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-hope-after-loss', 'es', 'description', 'El llanto puede durar toda la noche, pero la alegría viene por la mañana. Una oración para creer en eso.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-hope-after-loss', 'es', 'transcript', '# Esperanza Después de la Pérdida

Oh Señor, mi corazón está cargado de tristeza, y el peso de mi pérdida se siente insoportable. En los momentos de silencio, cuando las lágrimas caen y los recuerdos inundan mi mente, me vuelvo a Ti, buscando el consuelo que solo Tú puedes dar. Tu Palabra dice: "El llanto puede durar toda la noche, pero la alegría viene por la mañana". Sin embargo, ahora mismo, la mañana se siente tan distante, y la noche parece interminable.

Lucho por creer que la alegría encontrará su camino de regreso a mi vida. Ayúdame, Dios, a aferrarme a la esperanza que has prometido. Soy como un barco perdido en el mar, sacudido por las olas del dolor. Sé mi ancla, firme y segura, cuando todo lo demás se siente incierto.

Conoces las profundidades de mi corazón, el dolor no expresado, el anhelo por lo que una vez fue. En mis momentos más oscuros, recuérdame que estás cerca, recogiendo mis lágrimas, entendiendo mis clamores. Dame la fuerza para enfrentar cada día, para confiar en que Tu plan tiene un propósito incluso cuando no puedo verlo.

Guíame hacia la sanación, Señor. Que Tu amor sea la luz que rompa las sombras de mi dolor. Ayúdame a creer que la alegría volverá, que Tus promesas son verdaderas, y que la mañana llegará. Amén.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-big-decision', 'es', 'title', 'Enfrentando una Gran Decisión');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-big-decision', 'es', 'description', '¿Izquierda o derecha? ¿Quedarse o irse? Una oración por claridad cuando el camino se divide.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-big-decision', 'es', 'transcript', '# Enfrentando una Gran Decisión

Señor, Tú conoces el peso que se asienta en mi corazón mientras estoy en esta encrucijada. Me siento dividido e incierto, sin saber qué camino elegir. Tu Palabra me dice que si me falta sabiduría, debo pedirte, que das generosamente a todos sin reproche. Aquí estoy, pidiendo, buscando Tu guía y claridad. Conoces los deseos y temores que giran dentro de mí. Ves el futuro que yo no puedo ver. Anhelo confiar en Tu entendimiento en lugar de apoyarme en mi perspectiva limitada. Ayúdame a reconocerte en todos mis caminos, confiando en que harás rectas mis sendas. Concédeme paz en la espera y valor para seguir la dirección que reveles. Afirma mi corazón, Señor, cuando la ansiedad susurra dudas. Llena mi ser con Tu presencia y recuérdame que dondequiera que vaya, Tú estás conmigo. Pongo mi decisión en Tus manos, creyendo que estás obrando todas las cosas para bien. Guíame, Padre, con Tu mano gentil e inquebrantable. Amén.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-gods-will', 'es', 'title', 'Conociendo la Voluntad de Dios');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-gods-will', 'es', 'description', '¿Qué quiere Dios que haga? Una oración para escuchar Su voz por encima del ruido.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-gods-will', 'es', 'transcript', '# Conociendo la Voluntad de Dios

Querido Dios, vengo ante Ti sintiéndome abrumado por las decisiones que tengo por delante. Mi corazón está inquieto y mi mente nublada por la duda. Anhelo escuchar Tu voz guiándome a través de este laberinto de decisiones. Tú prometes en Tu Palabra que si me falta sabiduría, debo pedírtela, y Tú la darás generosamente sin reproche. Así que aquí estoy, Señor, pidiendo esa sabiduría.

Concédeme claridad, Padre, para discernir Tu voluntad para mi vida. Ayúdame a silenciar el ruido y las distracciones que me alejan de Tu suave y apacible voz. Quiero seguir el camino que has trazado para mí, pero me cuesta ver el camino. Como una lámpara a mis pies y una luz en mi camino, guíame con Tu verdad y abre mi corazón a Tu dirección.

Enséñame a confiar en Ti con todo mi corazón y a no apoyarme en mi propia prudencia. Ayúdame a reconocerte en todos mis caminos, sabiendo que Tú enderezarás mis veredas. Guárdame del miedo y la duda, y lléname de una paz que sobrepasa todo entendimiento. Pongo mi confianza en Ti, sabiendo que Tú tienes mi futuro en Tus manos. Amén.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-patience-in-waiting', 'es', 'title', 'Paciencia en la Espera');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-patience-in-waiting', 'es', 'description', 'La respuesta aún no ha llegado. Una oración para el insoportable intermedio.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-patience-in-waiting', 'es', 'transcript', '# Paciencia en la Espera

Dios, vengo a Ti con un corazón lleno de preguntas y una mente inquieta. Estoy en este lugar de espera, y a veces se siente tan insoportable. Sé que Tus caminos son más altos que los míos, y Tu tiempo es perfecto, sin embargo, lucho por encontrar paz en esta demora. Siento el peso de la incertidumbre presionando sobre mí, y es difícil mantener la paciencia cuando las respuestas parecen tan lejanas.

Me recuerdas a través de Tu palabra que "los que esperan a Jehová tendrán nuevas fuerzas". Necesito esa fuerza ahora más que nunca, Señor. Necesito el valor para confiar en Tus promesas y la gracia para aceptar que Tus planes para mí son buenos, incluso cuando no puedo ver el camino por delante.

Por favor, ayúdame a convertir mis pensamientos ansiosos en oraciones y mis dudas en confianza. Anhelo apoyarme en Tus brazos eternos, encontrar descanso en Tu presencia mientras espero. Concédeme la paciencia para soportar esta temporada, sabiendo que Tú estás obrando todas las cosas para mi bien. Amén.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-new-beginning', 'es', 'title', 'Oración por un Nuevo Comienzo');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-new-beginning', 'es', 'description', 'Cerrando un capítulo, abriendo otro. Una oración por el valor para avanzar.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-new-beginning', 'es', 'transcript', '# Oración por un Nuevo Comienzo

Dios, me presento ante Ti en una encrucijada, sintiendo el peso de lo que queda atrás y la incertidumbre de lo que espera. Al prepararme para cerrar este capítulo y adentrarme en lo desconocido, pido Tu guía y sabiduría para iluminar mi camino. Tu palabra me recuerda que "Reconócelo en todos tus caminos, y él enderezará tus veredas." Anhelo confiar en esa promesa, no apoyarme en mi propia prudencia, sino descansar en la seguridad de que Tú estás conmigo.

Señor, concédeme el valor para abrazar este nuevo comienzo, para avanzar con fe, incluso cuando el camino no esté claro. Ayúdame a soltar los miedos que me retienen y a confiar en que has preparado algo hermoso por delante. Permíteme caminar en Tu fuerza, sabiendo que pase lo que pase, me has equipado para este viaje.

Te traigo mis esperanzas y sueños, confiando en que los moldearás conforme a Tu voluntad. Llena mi corazón de paz y mi espíritu de determinación. Estoy agradecido por Tu constante presencia, por ser mi guía y mi refugio. Al avanzar, que siempre busque Tu dirección y encuentre consuelo en Tu amor inagotable. Amén.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-trusting-gods-timing', 'es', 'title', 'Confiando en el Tiempo de Dios');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-trusting-gods-timing', 'es', 'description', 'Está tardando demasiado. ¿O no? Una oración para confiar en que el reloj de Dios es perfecto.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'prayer', 'pr-trusting-gods-timing', 'es', 'transcript', '# Confiando en el Tiempo de Dios

Señor, vengo a Ti con un corazón lleno de preguntas, sintiendo el peso de decisiones que parecen prolongarse sin resolución. Confieso mi impaciencia, mi deseo de respuestas ahora, y mi lucha por esperar con fe. Sabes lo difícil que es para mí confiar cuando no puedo ver el camino por delante. Sin embargo, recuerdo Tu promesa de que "todo tiene su tiempo, y todo lo que se quiere debajo del cielo tiene su hora." Te pido que me ayudes a creer en Tu tiempo perfecto, incluso cuando parece que mis oraciones se encuentran con el silencio.

Pongo mis planes ante Ti, reconociendo que Tus caminos son más altos que los míos. Te pido el valor para soltar lo que creo que debería suceder y cuándo. Dame paz en la espera, y ayúdame a ver la belleza en el proceso, no solo en el destino. Guía mis pasos, Señor, y abre mi corazón a Tu sabiduría. Que no me apoye en mi propio entendimiento, sino que confíe en Tu amor y guía infalibles.

Fortalece mi fe para descansar en el conocimiento de que Tú estás obrando, incluso cuando no puedo verlo. Enséñame a abrazar Tu tiempo, sabiendo que harás todas las cosas hermosas en su momento. Gracias por ser mi constante, mi guía y mi esperanza inquebrantable. Amén.');
